{"command":"cd /workspace && cat > internal/formatter/common.go <<'EOF'
// Package formatter implements the XML, HTML and JSON beautifiers.
package formatter

import (
	"io"
	"regexp"
	"strings"
	"unicode/utf8"

	"github.com/fatih/color"
	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/ianaindex"
	"golang.org/x/text/encoding/unicode"
)

// ColorMode describes how the colorized output should be handled.
type ColorMode int

const (
	// ColorsDefault enables colors only when the output is a terminal.
	ColorsDefault ColorMode = iota
	// ColorsForced always enables colors.
	ColorsForced
	// ColorsDisabled never emits colors.
	ColorsDisabled
)

var (
	tagColor     = color.New(color.FgYellow)
	attrColor    = color.New(color.FgGreen)
	commentColor = color.New(color.FgHiBlue)
)

func applyColorMode(mode ColorMode) {
	switch mode {
	case ColorsForced:
		color.NoColor = false
	case ColorsDisabled:
		color.NoColor = true
	}
}

type output struct {
	w io.Writer
}

func (o *output) write(parts ...string) {
	for _, p := range parts {
		io.WriteString(o.w, p)
	}
}

// newLine returns the line separator with the indentation for the given level.
// When no indentation is used the formatters produce a single line.
func newLine(indent string, level int) string {
	if indent == "" {
		return ""
	}
	if level < 0 {
		level = 0
	}
	return "\n" + strings.Repeat(indent, level)
}

func lineBreak(indent string) string {
	if indent == "" {
		return ""
	}
	return "\n"
}

var (
	leadingSpacesRe  = regexp.MustCompile(`^ *\n +`)
	trailingSpacesRe = regexp.MustCompile(`[ \n]*\n +$`)
)

// normalizeSpaces re-indents the leading line of a text block and cleans up
// the trailing whitespace so that the closing tag gets properly aligned.
func normalizeSpaces(text string, indent string, level int) string {
	if leadingSpacesRe.MatchString(text) {
		text = leadingSpacesRe.ReplaceAllString(text, "\n"+strings.Repeat(indent, level))
	}
	if trailingSpacesRe.MatchString(text) {
		text = trailingSpacesRe.ReplaceAllString(text, "\n"+strings.Repeat(indent, level-1))
	}
	return strings.TrimRight(text, " ")
}

// escapeAttr escapes an attribute value for output within double quotes.
func escapeAttr(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); {
		r, width := utf8.DecodeRuneInString(s[i:])
		i += width
		switch r {
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '\t':
			b.WriteString("&#x9;")
		case '\n':
			b.WriteString("&#xA;")
		case '\r':
			b.WriteString("&#xD;")
		default:
			if !isInCharacterRange(r) || (r == utf8.RuneError && width == 1) {
				b.WriteString("\uFFFD")
			} else {
				b.WriteRune(r)
			}
		}
	}
	return b.String()
}

func isInCharacterRange(r rune) bool {
	return r == 0x09 ||
		r == 0x0A ||
		r == 0x0D ||
		r >= 0x20 && r <= 0xD7FF ||
		r >= 0xE000 && r <= 0xFFFD ||
		r >= 0x10000 && r <= 0x10FFFF
}

// CharsetReader converts the input declared with the given charset to UTF-8.
func CharsetReader(charset string, input io.Reader) (io.Reader, error) {
	var enc encoding.Encoding
	if strings.EqualFold(charset, "utf-16") {
		enc = unicode.UTF8
	} else {
		var err error
		enc, err = ianaindex.IANA.Encoding(charset)
		if err != nil {
			return nil, err
		}
	}
	return enc.NewDecoder().Reader(input), nil
}
EOF
echo done"}

