package formatter

import (
	"bufio"
	"encoding/xml"
	"io"
	"strings"

	"golang.org/x/net/html"
)

type tokenKind int

const (
	tokenNone tokenKind = iota
	tokenStart
	tokenEnd
	tokenText
	tokenDirective
	tokenOther
)

const xmlNamespace = "http://www.w3.org/XML/1998/namespace"

// FormatXml reads XML tokens from the reader and writes the beautified
// document to the writer. The output does not end with a line break.
func FormatXml(reader io.Reader, writer io.Writer, indent string, colors ColorMode) error {
	applyColorMode(colors)

	br := bufio.NewReader(reader)
	decoder := xml.NewDecoder(br)
	decoder.Strict = false
	decoder.CharsetReader = CharsetReader

	out := &output{w: writer}
	level := 0
	lastToken := tokenNone
	tagOpen := false
	nsMap := map[string]string{xmlNamespace: "xml"}

	qualify := func(name xml.Name) string {
		if name.Space == "" {
			return name.Local
		}
		if prefix, ok := nsMap[name.Space]; ok {
			if prefix == "" {
				return name.Local
			}
			return prefix + ":" + name.Local
		}
		return name.Space + ":" + name.Local
	}

	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}

		switch t := token.(type) {
		case xml.ProcInst:
			out.write(tagColor.Sprint("<?"), t.Target)
			inst := strings.TrimSpace(string(t.Inst))
			for _, pair := range strings.Split(inst, " ") {
				kv := strings.SplitN(pair, "=", 2)
				out.write(" ", kv[0], attrColor.Sprint("="+kv[1]))
			}
			out.write(tagColor.Sprint("?>"), lineBreak(indent))

		case xml.StartElement:
			for _, attr := range t.Attr {
				if attr.Name.Space == "xmlns" {
					if nsMap[attr.Value] == "" {
						nsMap[attr.Value] = attr.Name.Local
					}
				} else if attr.Name.Space == "" && attr.Name.Local == "xmlns" {
					nsMap[attr.Value] = ""
				}
			}
			if tagOpen {
				out.write(tagColor.Sprint(">"))
			}
			if level > 0 {
				out.write(newLine(indent, level))
			}
			out.write(tagColor.Sprint("<" + qualify(t.Name)))
			for _, attr := range t.Attr {
				out.write(" ", qualify(attr.Name), attrColor.Sprint(`="`+escapeAttr(attr.Value)+`"`))
			}
			tagOpen = true
			lastToken = tokenStart
			level++

		case xml.CharData:
			text := string(t)
			if strings.TrimSpace(text) == "" {
				continue
			}
			if tagOpen {
				out.write(tagColor.Sprint(">"))
				tagOpen = false
			}
			text = normalizeSpaces(text, indent, level)
			if strings.ContainsAny(text, "<&") {
				out.write("<![CDATA[", text, "]]>")
			} else {
				out.write(text)
			}
			lastToken = tokenText

		case xml.Comment:
			if tagOpen {
				out.write(tagColor.Sprint(">"))
				tagOpen = false
			}
			if level == 0 {
				out.write(commentColor.Sprint("<!--"), commentColor.Sprint(string(t)), commentColor.Sprint("-->"), lineBreak(indent))
			} else {
				if lastToken != tokenText {
					out.write(newLine(indent, level))
				}
				out.write(commentColor.Sprint("<!--"), commentColor.Sprint(string(t)), commentColor.Sprint("-->"))
			}

		case xml.Directive:
			if tagOpen {
				out.write(tagColor.Sprint(">"))
				tagOpen = false
			}
			if level == 0 {
				out.write(commentColor.Sprint("<!"+string(t)+">"), lineBreak(indent))
			} else {
				if lastToken != tokenText {
					out.write(newLine(indent, level))
				}
				out.write(commentColor.Sprint("<!" + string(t) + ">"))
			}
			lastToken = tokenDirective
			// The rest of the document is treated as HTML.
			return formatHtmlTokens(html.NewTokenizer(br), out, indent, level)

		case xml.EndElement:
			level--
			switch lastToken {
			case tokenStart:
				out.write(tagColor.Sprint("/>"))
				tagOpen = false
			case tokenText, tokenDirective:
				out.write(tagColor.Sprint("</" + qualify(t.Name) + ">"))
			default:
				if lastToken == tokenEnd {
					out.write(newLine(indent, level))
				}
				out.write(tagColor.Sprint("</" + qualify(t.Name) + ">"))
			}
			lastToken = tokenEnd
		}
	}

	return nil
}
EOF
