// FormatJson reads JSON tokens from the reader and writes the beautified
// document to the writer. The output does not end with a line break.
func FormatJson(reader io.Reader, writer io.Writer, indent string, colors ColorMode) error {
	applyColorMode(colors)

	decoder := json.NewDecoder(reader)
	decoder.UseNumber()
	out := &output{w: writer}

	level := 0
	counts := []int{0}
	kinds := []containerKind{containerTop}
	expectKey := false
	seenTopValue := false

	indentFor := func(l int) string {
		return strings.Repeat(indent, l)
	}
	separator := func(count int) string {
		if count > 0 {
			return "," + lineBreak(indent)
		}
		return ""
	}
	// valuePrefix writes whatever has to precede a new value (scalar or container).
	valuePrefix := func() {
		switch kinds[level] {
		case containerArray:
			out.write(separator(counts[level]), indentFor(level))
		case containerTop:
			if seenTopValue {
				count := 0
				if len(counts) > 1 {
					count = counts[1]
				}
				out.write(separator(count), indentFor(1))
			}
			seenTopValue = true
		}
	}
	completeValue := func() {
		counts[level]++
		if kinds[level] == containerObject {
			expectKey = true
		}
	}

	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}

		switch t := token.(type) {
		case json.Delim:
			switch t {
