				valuePrefix()
				out.write(tagColor.Sprint(string(t)), lineBreak(indent))
				level++
				kind := containerArray
				if t == '{' {
					kind = containerObject
				}
				if len(counts) <= level {
					counts = append(counts, 0)
					kinds = append(kinds, kind)
				} else {
					counts[level] = 0
					kinds[level] = kind
				}
				expectKey = kind == containerObject
			case '}', ']':
				level--
				out.write(newLine(indent, level), tagColor.Sprint(string(t)))
				completeValue()
			}
		case string:
			if kinds[level] == containerObject && expectKey {
				out.write(separator(counts[level]), indentFor(level), commentColor.Sprint(strconv.Quote(t)), ": ")
				expectKey = false
				continue
			}
			valuePrefix()
			out.write(attrColor.Sprint(strconv.Quote(t)))
			completeValue()
		case json.Number:
			valuePrefix()
			out.write(attrColor.Sprint(t.String()))
			completeValue()
		case bool:
			valuePrefix()
			out.write(attrColor.Sprint(strconv.FormatBool(t)))
			completeValue()
		case nil:
			valuePrefix()
			out.write(attrColor.Sprint("null"))
			completeValue()
		}
	}

	return nil
}
