// SelectAttr returns the value of the attribute with the given (qualified) name.
func (n *Node) SelectAttr(name string) string {
	if n.Type == AttributeNode {
		if n.Data == name {
			return n.InnerText()
		}
		return ""
	}
	for _, attr := range n.Attr {
		if attr.Name.Local == name || (attr.Name.Space != "" && attr.Name.Space+":"+attr.Name.Local == name) {
			return attr.Value
		}
	}
	return ""
}

func escapeText(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '&':
			b.WriteString("&amp;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

func qualifiedName(name xml.Name) string {
	if name.Space != "" {
		return name.Space + ":" + name.Local
	}
	return name.Local
}

func (n *Node) qualifiedData() string {
	if n.Prefix != "" {
		return n.Prefix + ":" + n.Data
	}
	return n.Data
}

func outputXML(b *strings.Builder, n *Node) {
	switch n.Type {
	case TextNode:
		b.WriteString(escapeText(n.Data))
		return
	case CharDataNode:
		b.WriteString("<![CDATA[")
		b.WriteString(n.Data)
		b.WriteString("]]>")
		return
	case CommentNode:
		b.WriteString("<!--")
		b.WriteString(n.Data)
		b.WriteString("-->")
		return
	case NotationNode:
		b.WriteString("<!")
		b.WriteString(n.Data)
		b.WriteString(">")
		return
	case DeclarationNode:
		b.WriteString("<?" + n.Data)
	default:
		b.WriteString("<" + n.qualifiedData())
	}

	for _, attr := range n.Attr {
		b.WriteString(" ")
		b.WriteString(qualifiedName(attr.Name))
		b.WriteString(`="`)
		b.WriteString(escapeText(attr.Value))
		b.WriteString(`"`)
	}
	if n.Type == DeclarationNode {
		b.WriteString("?>")
	} else {
		b.WriteString(">")
	}
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		outputXML(b, child)
	}
	if n.Type != DeclarationNode {
		b.WriteString("</" + n.qualifiedData() + ">")
	}
}

// OutputXML serializes the node back to XML. When self is false only the
// children are serialized.
func (n *Node) OutputXML(self bool) string {
	var b strings.Builder
	if self && n.Type != DocumentNode {
		outputXML(&b, n)
	} else {
		for child := n.FirstChild; child != nil; child = child.NextSibling {
			outputXML(&b, child)
		}
	}
	return b.String()
}

// AddAttr appends an attribute to the node.
func AddAttr(n *Node, key, val string) {
	n.Attr = append(n.Attr, Attr{Name: xml.Name{Local: key}, Value: val})
}

// AddChild appends a child node.
func AddChild(parent, n *Node) {
	n.Parent = parent
	n.NextSibling = nil
	if parent.FirstChild == nil {
		parent.FirstChild = n
		n.PrevSibling = nil
	} else {
		parent.LastChild.NextSibling = n
		n.PrevSibling = parent.LastChild
	}
	parent.LastChild = n
}

// AddSibling appends a node after the last sibling of the given node.
func AddSibling(sibling, n *Node) {
	for t := sibling.NextSibling; t != nil; t = t.NextSibling {
		sibling = t
	}
	n.Parent = sibling.Parent
	sibling.NextSibling = n
	n.PrevSibling = sibling
	if sibling.Parent != nil {
		sibling.Parent.LastChild = n
	}
}
