			break
		}
	}
	return n, nil
}

type parser struct {
	decoder      *xml.Decoder
	doc          *Node
	level        int
	prev         *Node
	raw          *bytes.Buffer
	space2prefix map[string]string
}

// Parse builds the document tree from the reader.
func Parse(r io.Reader, opts Options) (*Node, error) {
	raw := &bytes.Buffer{}
	rec := &recorder{r: bufio.NewReader(r), buf: raw}
	p := &parser{
		decoder:      xml.NewDecoder(rec),
		doc:          &Node{Type: DocumentNode},
		space2prefix: map[string]string{"http://www.w3.org/XML/1998/namespace": "xml"},
		raw:          raw,
	}
	p.prev = p.doc
	p.decoder.Strict = opts.Strict
	charsetReader := opts.CharsetReader
	p.decoder.CharsetReader = func(charset string, input io.Reader) (io.Reader, error) {
		if charsetReader == nil {
			return nil, errors.New("unsupported charset: \"" + charset + "\"")
		}
		converted, err := charsetReader(charset, input)
		if err != nil {
			return nil, err
		}
		if converted == nil {
			return nil, nil
		}
		// Keep recording the (converted) bytes to stay aligned with the decoder offsets.
		return &recorder{r: bufio.NewReader(converted), buf: raw}, nil
	}

	if err := p.parse(); err != nil {
		return nil, err
	}
	for child := p.doc.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == ElementNode {
			return p.doc, nil
		}
	}
