				if att.Name.Space == "xmlns" {
					if p.space2prefix[att.Value] == "" {
						p.space2prefix[att.Value] = att.Name.Local
					}
				} else if att.Name.Space == "" && att.Name.Local == "xmlns" {
					p.space2prefix[att.Value] = ""
				}
			}
			node := &Node{
				Type:         ElementNode,
				Data:         tok.Name.Local,
				NamespaceURI: tok.Name.Space,
				Attr:         make([]Attr, 0, len(tok.Attr)),
				level:        p.level,
			}
			if tok.Name.Space != "" {
				if prefix, ok := p.space2prefix[tok.Name.Space]; ok {
					node.Prefix = prefix
				} else {
					node.Prefix = tok.Name.Space
				}
			}
			for _, att := range tok.Attr {
				name := xml.Name{Local: att.Name.Local}
				if att.Name.Space != "" {
					if prefix, ok := p.space2prefix[att.Name.Space]; ok && prefix != "" {
						name.Space = prefix
					} else {
						name.Space = att.Name.Space
					}
				}
				node.Attr = append(node.Attr, Attr{Name: name, Value: att.Value, NamespaceURI: att.Name.Space})
			}
			p.addNode(node)
			p.prev = node
			p.level++

		case xml.EndElement:
			p.level--

		case xml.CharData:
			nodeType := TextNode
			rawBytes := p.raw.Bytes()
			if int(start) < len(rawBytes) && bytes.HasPrefix(bytes.ToUpper(rawBytes[start:]), []byte("<![CDATA[")) {
				nodeType = CharDataNode
			}
			if nodeType == TextNode && p.level <= p.prev.level && strings.TrimSpace(string(tok)) == "" {
				continue
			}
			node := &Node{Type: nodeType, Data: string(tok), level: p.level}
			p.addNode(node)

		case xml.Comment:
			node := &Node{Type: CommentNode, Data: string(tok), level: p.level}
			p.addNode(node)

		case xml.ProcInst:
			if p.prev.Type != DeclarationNode {
				p.level++
			}
			node := &Node{Type: DeclarationNode, Data: tok.Target, level: p.level}
			for _, pair := range strings.Split(string(tok.Inst), " ") {
				pair = strings.TrimSpace(pair)
				if i := strings.Index(pair, "="); i > 0 {
					AddAttr(node, pair[:i], strings.Trim(pair[i+1:], `"`))
				}
			}
