				AddChild(p.doc, node)
			} else if p.level > 1 {
				AddChild(p.prev, node)
			}
			p.prev = node

		case xml.Directive:
			node := &Node{Type: NotationNode, Data: string(tok), level: p.level}
			p.addNode(node)
		}
	}
