package xpath

import (
	"fmt"
	"strings"
	"unicode"
)

type itemType int

const (
	itemEOF itemType = iota
	itemName
	itemNumber
	itemString
	itemOp // operators and punctuation
	itemAxis
)

type item struct {
	typ itemType
	val string
}

type lexer struct {
	input string
	pos   int
	items []item
}

func isNameStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r)
}

func isNameChar(r rune) bool {
	return r == '_' || r == '-' || r == '.' || unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r)
}

func tokenize(input string) ([]item, error) {
	var items []item
	runes := []rune(input)
	i := 0
	for i < len(runes) {
		r := runes[i]
		switch {
		case unicode.IsSpace(r):
			i++
		case r == '"' || r == '\'':
			quote := r
			j := i + 1
			for j < len(runes) && runes[j] != quote {
				j++
			}
			if j >= len(runes) {
				return nil, fmt.Errorf("unterminated string literal")
			}
			items = append(items, item{itemString, string(runes[i+1 : j])})
			i = j + 1
		case unicode.IsDigit(r) || (r == '.' && i+1 < len(runes) && unicode.IsDigit(runes[i+1])):
			j := i
			for j < len(runes) && unicode.IsDigit(runes[j]) {
				j++
			}
			if j < len(runes) && runes[j] == '.' {
				j++
				for j < len(runes) && unicode.IsDigit(runes[j]) {
					j++
				}
			}
			items = append(items, item{itemNumber, string(runes[i:j])})
			i = j
		case r == '/' && i+1 < len(runes) && runes[i+1] == '/':
			items = append(items, item{itemOp, "//"})
			i += 2
		case r == '.' && i+1 < len(runes) && runes[i+1] == '.':
			items = append(items, item{itemOp, ".."})
			i += 2
		case r == ':' && i+1 < len(runes) && runes[i+1] == ':':
			items = append(items, item{itemOp, "::"})
			i += 2
		case r == '!' && i+1 < len(runes) && runes[i+1] == '=':
			items = append(items, item{itemOp, "!="})
			i += 2
		case r == '<' && i+1 < len(runes) && runes[i+1] == '=':
			items = append(items, item{itemOp, "<="})
			i += 2
		case r == '>' && i+1 < len(runes) && runes[i+1] == '=':
			items = append(items, item{itemOp, ">="})
			i += 2
		case strings.ContainsRune("/.()[]@,|=<>+-*$", r):
			items = append(items, item{itemOp, string(r)})
			i++
		case isNameStart(r):
			j := i
			for j < len(runes) && isNameChar(runes[j]) {
				j++
			}
			// QName: prefix:local (but not an axis specifier "::")
			if j < len(runes) && runes[j] == ':' && !(j+1 < len(runes) && runes[j+1] == ':') {
				k := j + 1
				if k < len(runes) && (isNameStart(runes[k]) || runes[k] == '*') {
					if runes[k] == '*' {
						k++
					} else {
						for k < len(runes) && isNameChar(runes[k]) {
							k++
						}
					}
					items = append(items, item{itemName, string(runes[i:k])})
					i = k
					continue
				}
			}
			items = append(items, item{itemName, string(runes[i:j])})
			i = j
		default:
			return nil, fmt.Errorf("unexpected character %q", r)
		}
	}
	items = append(items, item{itemEOF, ""})
	return items, nil
}
EOF
