cd /workspace && cat > internal/xpath/parser.go <<'EOF'
package xpath

import (
	"errors"
	"strconv"
)

// ErrSyntax is returned for malformed expressions.
var ErrSyntax = errors.New("unable to parse the XPath query")

type expr interface{}

type numberLit float64
type stringLit string

type funcCall struct {
	name string
	args []expr
}

type binaryOp struct {
	op          string
	left, right expr
}

type unaryNeg struct {
	operand expr
}

type unionExpr struct {
	left, right expr
}

type rootExpr struct{}

type contextExpr struct{}

type pathExpr struct {
	start expr // nil means the context node
	steps []*step
}

type filterExpr struct {
	primary    expr
	predicates []expr
}

type testKind int

const (
	testName testKind = iota // QName or prefix:*
	testStar
	testNodeType
)

type nodeTest struct {
	kind   testKind
	prefix string
	local  string
	typ    string // node, text, comment, processing-instruction
}

type step struct {
	axis       string
	test       nodeTest
	predicates []expr
}

var functionArity = map[string][2]int{
	"boolean":          {1, 1},
	"ceiling":          {1, 1},
	"concat":           {2, -1},
	"contains":         {2, 2},
	"count":            {1, 1},
	"ends-with":        {2, 2},
	"false":            {0, 0},
	"floor":            {1, 1},
	"last":             {0, 0},
	"local-name":       {0, 1},
	"lower-case":       {1, 1},
	"matches":          {2, 2},
	"name":             {0, 1},
	"namespace-uri":    {0, 1},
	"normalize-space":  {1, 1},
	"not":              {1, 1},
	"number":           {0, 1},
	"position":         {0, 0},
	"replace":          {3, 3},
	"reverse":          {1, 1},
	"round":            {1, 1},
	"starts-with":      {2, 2},
	"string":           {0, 1},
	"string-join":      {2, 2},
	"string-length":    {1, 1},
	"substring":        {2, 3},
	"substring-after":  {2, 2},
	"substring-before": {2, 2},
	"sum":              {1, 1},
	"translate":        {3, 3},
	"true":             {0, 0},
}

var axisNames = map[string]bool{
	"ancestor": true, "ancestor-or-self": true, "attribute": true, "child": true,
	"descendant": true, "descendant-or-self": true, "following": true,
	"following-sibling": true, "parent": true, "preceding": true,
	"preceding-sibling": true, "self": true,
}

type parser struct {
	items []item
	pos   int
}

func (p *parser) peek() item {
	return p.items[p.pos]
}

func (p *parser) peekAt(n int) item {
	if p.pos+n < len(p.items) {
		return p.items[p.pos+n]
	}
	return p.items[len(p.items)-1]
}

func (p *parser) next() item {
	it := p.items[p.pos]
	if p.pos < len(p.items)-1 {
		p.pos++
	}
	return it
}

func (p *parser) isOp(val string) bool {
	it := p.peek()
	return it.typ == itemOp && it.val == val
}

func (p *parser) expectOp(val string) error {
	if !p.isOp(val) {
		return ErrSyntax
	}
	p.next()
	return nil
}

// isOperatorName reports whether the current name token should be treated as
// an operator (and/or/div/mod) given the previous token.
func (p *parser) prevAllowsOperand() bool {
	if p.pos == 0 {
		return true
	}
	prev := p.items[p.pos-1]
	switch prev.typ {
	case itemOp:
		switch prev.val {
		case ")", "]", ".", "..":
			return false
		}
		return true
	case itemAxis:
		return true
	}
	return false
}

func parse(input string) (expr, error) {
	items, err := tokenize(input)
	if err != nil {
		return nil, ErrSyntax
	}
	p := &parser{items: items}
	if p.peek().typ == itemEOF {
		return nil, ErrSyntax
	}
	e, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	return e, nil
}

func (p *parser) nameOp(name string) bool {
	it := p.peek()
	return it.typ == itemName && it.val == name && !p.prevAllowsOperand()
}

func (p *parser) parseOr() (expr, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.nameOp("or") {
		p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{"or", left, right}
	}
	return left, nil
}

func (p *parser) parseAnd() (expr, error) {
	left, err := p.parseEquality()
	if err != nil {
		return nil, err
	}
	for p.nameOp("and") {
		p.next()
		right, err := p.parseEquality()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{"and", left, right}
	}
	return left, nil
}

func (p *parser) parseEquality() (expr, error) {
	left, err := p.parseRelational()
	if err != nil {
		return nil, err
	}
	for p.isOp("=") || p.isOp("!=") {
		op := p.next().val
		right, err := p.parseRelational()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{op, left, right}
	}
	return left, nil
}

func (p *parser) parseRelational() (expr, error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.isOp("<") || p.isOp(">") || p.isOp("<=") || p.isOp(">=") {
		op := p.next().val
		right, err := p.parseAdditive()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{op, left, right}
	}
	return left, nil
}

func (p *parser) parseAdditive() (expr, error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") {
		op := p.next().val
		right, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{op, left, right}
	}
	return left, nil
}

func (p *parser) parseMultiplicative() (expr, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		var op string
		if p.isOp("*") && !p.prevAllowsOperand() {
			op = "*"
		} else if p.nameOp("div") {
			op = "div"
		} else if p.nameOp("mod") {
			op = "mod"
		} else {
			break
		}
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &binaryOp{op, left, right}
	}
	return left, nil
}

func (p *parser) parseUnary() (expr, error) {
	if p.isOp("-") {
		p.next()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &unaryNeg{operand}, nil
	}
	return p.parseUnion()
}

func (p *parser) parseUnion() (expr, error) {
	left, err := p.parsePath()
	if err != nil {
		return nil, err
	}
	for p.isOp("|") {
		p.next()
		right, err := p.parsePath()
		if err != nil {
			return nil, err
		}
		left = &unionExpr{left, right}
	}
	return left, nil
}

func (p *parser) startsStep() bool {
	it := p.peek()
	switch it.typ {
	case itemName:
		return true
	case itemOp:
		switch it.val {
		case "@", ".", "..", "*":
			return true
		}
	}
	return false
}

func (p *parser) parsePath() (expr, error) {
	// Absolute location paths.
	if p.isOp("/") {
		p.next()
		path := &pathExpr{start: &rootExpr{}}
		if p.startsStep() {
			steps, err := p.parseRelativeSteps()
			if err != nil {
				return nil, err
			}
			path.steps = steps
		}
		return path, nil
	}
	if p.isOp("//") {
		p.next()
		if !p.startsStep() {
			return nil, ErrSyntax
		}
		steps, err := p.parseRelativeSteps()
		if err != nil {
			return nil, err
		}
		path := &pathExpr{start: &rootExpr{}}
		path.steps = append([]*step{descendantOrSelfStep()}, steps...)
		return path, nil
	}

	it := p.peek()
	isPrimary := false
	switch it.typ {
	case itemNumber, itemString:
		isPrimary = true
	case itemOp:
		if it.val == "(" || it.val == "$" {
			isPrimary = true
		}
	case itemName:
		// function call: name followed by "(" unless it is a node type test
		if p.peekAt(1).typ == itemOp && p.peekAt(1).val == "(" && !isNodeType(it.val) {
			isPrimary = true
		}
	}

	if isPrimary {
		primary, err := p.parsePrimary()
		if err != nil {
			return nil, err
		}
		var predicates []expr
		for p.isOp("[") {
			pred, err := p.parsePredicate()
			if err != nil {
				return nil, err
			}
			predicates = append(predicates, pred)
		}
		var start expr = primary
		if len(predicates) > 0 {
			start = &filterExpr{primary, predicates}
		}
		if p.isOp("/") || p.isOp("//") {
			path := &pathExpr{start: start}
			for p.isOp("/") || p.isOp("//") {
				if p.next().val == "//" {
					path.steps = append(path.steps, descendantOrSelfStep())
				}
				st, err := p.parseStep()
				if err != nil {
					return nil, err
				}
				path.steps = append(path.steps, st)
			}
			return path, nil
		}
		return start, nil
	}

	if !p.startsStep() {
		return nil, ErrSyntax
	}
	steps, err := p.parseRelativeSteps()
	if err != nil {
		return nil, err
	}
	return &pathExpr{start: nil, steps: steps}, nil
}

func descendantOrSelfStep() *step {
	return &step{axis: "descendant-or-self", test: nodeTest{kind: testNodeType, typ: "node"}}
}

func isNodeType(name string) bool {
	switch name {
	case "node", "text", "comment", "processing-instruction":
		return true
	}
	return false
}

func (p *parser) parseRelativeSteps() ([]*step, error) {
	var steps []*step
	st, err := p.parseStep()
	if err != nil {
		return nil, err
	}
	steps = append(steps, st)
	for p.isOp("/") || p.isOp("//") {
		if p.next().val == "//" {
			steps = append(steps, descendantOrSelfStep())
		}
		st, err := p.parseStep()
		if err != nil {
			return nil, err
		}
		steps = append(steps, st)
	}
	return steps, nil
}

func (p *parser) parseStep() (*step, error) {
	if p.isOp(".") {
		p.next()
		return &step{axis: "self", test: nodeTest{kind: testNodeType, typ: "node"}}, nil
	}
	if p.isOp("..") {
		p.next()
		return &step{axis: "parent", test: nodeTest{kind: testNodeType, typ: "node"}}, nil
	}

	st := &step{axis: "child"}
	if p.isOp("@") {
		p.next()
		st.axis = "attribute"
	} else if p.peek().typ == itemName && p.peekAt(1).typ == itemOp && p.peekAt(1).val == "::" {
		axis := p.next().val
		p.next()
		if !axisNames[axis] {
			return nil, ErrSyntax
		}
		st.axis = axis
	}

	it := p.peek()
	switch {
	case it.typ == itemOp && it.val == "*":
		p.next()
		st.test = nodeTest{kind: testStar}
	case it.typ == itemName:
		p.next()
		if p.isOp("(") {
			if !isNodeType(it.val) {
				return nil, ErrSyntax
			}
			p.next()
			if it.val == "processing-instruction" && p.peek().typ == itemString {
				p.next()
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			st.test = nodeTest{kind: testNodeType, typ: it.val}
		} else {
			prefix, local := splitQName(it.val)
			if local == "*" {
				st.test = nodeTest{kind: testStar, prefix: prefix}
			} else {
				st.test = nodeTest{kind: testName, prefix: prefix, local: local}
			}
		}
	default:
		return nil, ErrSyntax
	}

	for p.isOp("[") {
		pred, err := p.parsePredicate()
		if err != nil {
			return nil, err
		}
		st.predicates = append(st.predicates, pred)
	}
	return st, nil
}

func splitQName(name string) (string, string) {
	for i := 0; i < len(name); i++ {
		if name[i] == ':' {
			return name[:i], name[i+1:]
		}
	}
	return "", name
}

func (p *parser) parsePredicate() (expr, error) {
	if err := p.expectOp("["); err != nil {
		return nil, err
	}
	if p.isOp("]") {
		return nil, ErrSyntax
	}
	e, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp("]"); err != nil {
		return nil, err
	}
	return e, nil
}

func (p *parser) parsePrimary() (expr, error) {
	it := p.next()
	switch it.typ {
	case itemNumber:
		v, err := strconv.ParseFloat(it.val, 64)
		if err != nil {
			return nil, ErrSyntax
		}
		return numberLit(v), nil
	case itemString:
		return stringLit(it.val), nil
	case itemOp:
		switch it.val {
		case "(":
			e, err := p.parseOr()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return e, nil
		case "$":
			return nil, ErrSyntax
		}
	case itemName:
		arity, ok := functionArity[it.val]
		if !ok {
			return nil, ErrSyntax
		}
		if err := p.expectOp("("); err != nil {
			return nil, err
		}
		call := &funcCall{name: it.val}
		if !p.isOp(")") {
			for {
				arg, err := p.parseOr()
				if err != nil {
					return nil, err
				}
				call.args = append(call.args, arg)
				if p.isOp(",") {
					p.next()
					continue
				}
				break
			}
		}
		if err := p.expectOp(")"); err != nil {
			return nil, err
		}
		if len(call.args) < arity[0] || (arity[1] >= 0 && len(call.args) > arity[1]) {
			return nil, ErrSyntax
		}
		return call, nil
	}
	return nil, ErrSyntax
}
EOF
echo ok

