cd /workspace && cat > internal/xpath/eval.go <<'EOF'
package xpath

import (
	"errors"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Expr is a compiled XPath expression.
type Expr struct {
	root expr
}

// Compile parses the expression.
func Compile(query string) (*Expr, error) {
	e, err := parse(query)
	if err != nil {
		return nil, err
	}
	return &Expr{root: e}, nil
}

// NodeSet is an ordered list of nodes.
type NodeSet []Node

type context struct {
	node Node
	pos  int
	size int
}

// Evaluate runs the expression with the given node as the context node.
// The result is a NodeSet, float64, string, bool or int.
func (e *Expr) Evaluate(node Node) (interface{}, error) {
	return eval(e.root, &context{node: node, pos: 1, size: 1})
}

func sortNodes(nodes NodeSet) NodeSet {
	sort.SliceStable(nodes, func(i, j int) bool { return nodes[i].Order() < nodes[j].Order() })
	// dedup
	out := nodes[:0]
	for i, n := range nodes {
		if i > 0 && nodes[i-1] == n {
			continue
		}
		out = append(out, n)
	}
	return out
}

func eval(e expr, ctx *context) (interface{}, error) {
	switch t := e.(type) {
	case numberLit:
		return float64(t), nil
	case stringLit:
		return string(t), nil
	case *rootExpr:
		return NodeSet{rootOf(ctx.node)}, nil
	case *contextExpr:
		return NodeSet{ctx.node}, nil
	case *unaryNeg:
		v, err := eval(t.operand, ctx)
		if err != nil {
			return nil, err
		}
		return -toNumber(v), nil
	case *unionExpr:
		l, err := eval(t.left, ctx)
		if err != nil {
			return nil, err
		}
		r, err := eval(t.right, ctx)
		if err != nil {
			return nil, err
		}
		ln, ok1 := l.(NodeSet)
		rn, ok2 := r.(NodeSet)
		if !ok1 || !ok2 {
			return nil, errors.New("union operator requires node-sets")
		}
		merged := append(NodeSet{}, ln...)
		merged = append(merged, rn...)
		return sortNodes(merged), nil
	case *binaryOp:
		return evalBinary(t, ctx)
	case *funcCall:
		return evalFunc(t, ctx)
	case *filterExpr:
		v, err := eval(t.primary, ctx)
		if err != nil {
			return nil, err
		}
		nodes, ok := v.(NodeSet)
		if !ok {
			return nil, errors.New("predicates can only be applied to node-sets")
		}
		return applyPredicates(nodes, t.predicates, false)
	case *pathExpr:
		var nodes NodeSet
		if t.start == nil {
			nodes = NodeSet{ctx.node}
		} else {
			v, err := eval(t.start, ctx)
			if err != nil {
				return nil, err
			}
			ns, ok := v.(NodeSet)
			if !ok {
				return nil, errors.New("location path requires a node-set")
			}
			nodes = ns
		}
		for _, st := range t.steps {
			var err error
			nodes, err = evalStep(st, nodes)
			if err != nil {
				return nil, err
			}
		}
		return nodes, nil
	}
	return nil, fmt.Errorf("unsupported expression %T", e)
}

func rootOf(n Node) Node {
	for n.Parent() != nil {
		n = n.Parent()
	}
	return n
}

func isReverseAxis(axis string) bool {
	switch axis {
	case "ancestor", "ancestor-or-self", "preceding", "preceding-sibling":
		return true
	}
	return false
}

func axisNodes(axis string, n Node) NodeSet {
	var out NodeSet
	switch axis {
	case "child":
		for c := n.FirstChild(); c != nil; c = c.NextSibling() {
			out = append(out, c)
		}
	case "descendant":
		collectDescendants(n, &out)
	case "descendant-or-self":
		out = append(out, n)
		collectDescendants(n, &out)
	case "parent":
		if p := n.Parent(); p != nil {
			out = append(out, p)
		}
	case "ancestor":
		for p := n.Parent(); p != nil; p = p.Parent() {
			out = append(out, p)
		}
	case "ancestor-or-self":
		out = append(out, n)
		for p := n.Parent(); p != nil; p = p.Parent() {
			out = append(out, p)
		}
	case "following-sibling":
		if n.Type() != AttributeNode {
			for s := n.NextSibling(); s != nil; s = s.NextSibling() {
				out = append(out, s)
			}
		}
	case "preceding-sibling":
		if n.Type() != AttributeNode {
			for s := n.PrevSibling(); s != nil; s = s.PrevSibling() {
				out = append(out, s)
			}
		}
	case "following":
		for cur := n; cur != nil; cur = cur.Parent() {
			if cur.Type() == AttributeNode {
				continue
			}
			for s := cur.NextSibling(); s != nil; s = s.NextSibling() {
				out = append(out, s)
				collectDescendants(s, &out)
			}
		}
	case "preceding":
		var collected NodeSet
		for cur := n; cur != nil; cur = cur.Parent() {
			if cur.Type() == AttributeNode {
				continue
			}
			for s := cur.PrevSibling(); s != nil; s = s.PrevSibling() {
				var sub NodeSet
				sub = append(sub, s)
				collectDescendants(s, &sub)
				// reverse document order
				for i := len(sub) - 1; i >= 0; i-- {
					collected = append(collected, sub[i])
				}
			}
		}
		out = collected
	case "self":
		out = append(out, n)
	case "attribute":
		if n.Type() == ElementNode {
			out = append(out, n.Attributes()...)
		}
	}
	return out
}

func collectDescendants(n Node, out *NodeSet) {
	for c := n.FirstChild(); c != nil; c = c.NextSibling() {
		*out = append(*out, c)
		collectDescendants(c, out)
	}
}

func matchTest(test nodeTest, axis string, n Node) bool {
	switch test.kind {
	case testNodeType:
		switch test.typ {
		case "node":
			return true
		case "text":
			return n.Type() == TextNode
		case "comment":
			return n.Type() == CommentNode
		case "processing-instruction":
			return n.Type() == ProcessingInstructionNode
		}
		return false
	case testStar:
		principal := ElementNode
		if axis == "attribute" {
			principal = AttributeNode
		}
		if n.Type() != principal {
			return false
		}
		if test.prefix != "" {
			return n.Prefix() == test.prefix
		}
		return true
	case testName:
		principal := ElementNode
		if axis == "attribute" {
			principal = AttributeNode
		}
		if n.Type() != principal {
			return false
		}
		return n.LocalName() == test.local && n.Prefix() == test.prefix
	}
	return false
}

func evalStep(st *step, input NodeSet) (NodeSet, error) {
	var result NodeSet
	reverse := isReverseAxis(st.axis)
	for _, ctxNode := range input {
		var candidates NodeSet
		for _, n := range axisNodes(st.axis, ctxNode) {
			if matchTest(st.test, st.axis, n) {
				candidates = append(candidates, n)
			}
		}
		filtered, err := applyPredicates(candidates, st.predicates, reverse)
		if err != nil {
			return nil, err
		}
		result = append(result, filtered...)
	}
	return sortNodes(result), nil
}

// applyPredicates filters the nodes (given in axis order) with each predicate in turn.
func applyPredicates(nodes NodeSet, predicates []expr, reverse bool) (NodeSet, error) {
	_ = reverse
	for _, pred := range predicates {
		var kept NodeSet
		size := len(nodes)
		for i, n := range nodes {
			v, err := eval(pred, &context{node: n, pos: i + 1, size: size})
			if err != nil {
				return nil, err
			}
			keep := false
			switch pv := v.(type) {
			case float64:
				keep = pv == float64(i+1)
			case int:
				keep = pv == i+1
			default:
				keep = toBool(v)
			}
			if keep {
				kept = append(kept, n)
			}
		}
		nodes = kept
	}
	return nodes, nil
}

func toBool(v interface{}) bool {
	switch t := v.(type) {
	case NodeSet:
		return len(t) > 0
	case float64:
		return t != 0 && !math.IsNaN(t)
	case int:
		return t != 0
	case string:
		return t != ""
	case bool:
		return t
	}
	return false
}

func parseNumber(s string) float64 {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return math.NaN()
	}
	return v
}

func toNumber(v interface{}) float64 {
	switch t := v.(type) {
	case NodeSet:
		if len(t) == 0 {
			return math.NaN()
		}
		return parseNumber(t[0].Value())
	case float64:
		return t
	case int:
		return float64(t)
	case string:
		return parseNumber(t)
	case bool:
		return math.NaN()
	}
	return math.NaN()
}

func formatNumber(f float64) string {
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func toString(v interface{}) (string, error) {
	switch t := v.(type) {
	case NodeSet:
		if len(t) == 0 {
			return "", nil
		}
		return t[0].Value(), nil
	case float64:
		return formatNumber(t), nil
	case string:
		return t, nil
	case bool:
		return strconv.FormatBool(t), nil
	}
	return "", fmt.Errorf("unexpected type: %T", v)
}

func evalBinary(b *binaryOp, ctx *context) (interface{}, error) {
	switch b.op {
	case "or", "and":
		l, err := eval(b.left, ctx)
		if err != nil {
			return nil, err
		}
		lb := toBool(l)
		if b.op == "or" && lb {
			return true, nil
		}
		if b.op == "and" && !lb {
			return false, nil
		}
		r, err := eval(b.right, ctx)
		if err != nil {
			return nil, err
		}
		return toBool(r), nil
	}

	l, err := eval(b.left, ctx)
	if err != nil {
		return nil, err
	}
	r, err := eval(b.right, ctx)
	if err != nil {
		return nil, err
	}

	switch b.op {
	case "+", "-", "*", "div", "mod":
		x, y := toNumber(l), toNumber(r)
		switch b.op {
		case "+":
			return x + y, nil
		case "-":
			return x - y, nil
		case "*":
			return x * y, nil
		case "div":
			return x / y, nil
		case "mod":
			if math.IsNaN(x) || math.IsNaN(y) || math.IsInf(x, 0) || math.IsInf(y, 0) || int64(y) == 0 {
				return math.NaN(), nil
			}
			return float64(int64(x) % int64(y)), nil
		}
	case "=", "!=", "<", "<=", ">", ">=":
		return compare(b.op, l, r)
	}
	return nil, fmt.Errorf("unknown operator %s", b.op)
}

func compareNumbers(op string, x, y float64) bool {
	switch op {
	case "=":
		return x == y
	case "!=":
		return x != y
	case "<":
		return x < y
	case "<=":
		return x <= y
	case ">":
		return x > y
	case ">=":
		return x >= y
	}
	return false
}

func compareStrings(op string, x, y string) bool {
	switch op {
	case "=":
		return x == y
	case "!=":
		return x != y
	case "<":
		return x < y
	case "<=":
		return x <= y
	case ">":
		return x > y
	case ">=":
		return x >= y
	}
	return false
}

var errNilDeref = errors.New("runtime error: invalid memory address or nil pointer dereference")

func compare(op string, l, r interface{}) (interface{}, error) {
	ln, lIsNodes := l.(NodeSet)
	rn, rIsNodes := r.(NodeSet)

	switch {
	case lIsNodes && rIsNodes:
		for _, a := range ln {
			for _, b := range rn {
				if compareStrings(op, a.Value(), b.Value()) {
					return true, nil
				}
			}
		}
		return false, nil
	case lIsNodes || rIsNodes:
		nodes, other := ln, r
		flip := false
		if rIsNodes {
			nodes, other = rn, l
			flip = true
		}
		for _, n := range nodes {
			var ok bool
			switch o := other.(type) {
			case string:
				if flip {
					ok = compareStrings(op, o, n.Value())
				} else {
					ok = compareStrings(op, n.Value(), o)
				}
			case float64, int:
				num := toNumber(o)
				val, err := strconv.ParseFloat(n.Value(), 64)
				if err != nil {
					if op == "=" || op == "!=" {
						val = math.NaN()
					} else {
						return nil, err
					}
				}
				if flip {
					ok = compareNumbers(op, num, val)
				} else {
					ok = compareNumbers(op, val, num)
				}
			case bool:
				nb := len(nodes) > 0
				if flip {
					ok = compareBools(op, o, nb)
				} else {
					ok = compareBools(op, nb, o)
				}
				return ok, nil
			}
			if ok {
				return true, nil
			}
		}
		return false, nil
	}

	_, lIsBool := l.(bool)
	_, rIsBool := r.(bool)
	if lIsBool || rIsBool {
		if lIsBool && rIsBool {
			return compareBools(op, l.(bool), r.(bool)), nil
		}
		return nil, errNilDeref
	}
	ls, lIsStr := l.(string)
	rs, rIsStr := r.(string)
	if lIsStr && rIsStr {
		return compareStrings(op, ls, rs), nil
	}
	return compareNumbers(op, toNumber(l), toNumber(r)), nil
}

func compareBools(op string, x, y bool) bool {
	switch op {
	case "=":
		return x == y
	case "!=":
		return x != y
	}
	xi, yi := 0.0, 0.0
	if x {
		xi = 1
	}
	if y {
		yi = 1
	}
	return compareNumbers(op, xi, yi)
}

func nodeName(n Node) string {
	if n.Type() == RootNode {
		return ""
	}
	if n.Prefix() != "" {
		return n.Prefix() + ":" + n.LocalName()
	}
	return n.LocalName()
}

func argString(args []interface{}, i int) (string, error) {
	return toString(args[i])
}

func evalFunc(f *funcCall, ctx *context) (interface{}, error) {
	args := make([]interface{}, len(f.args))
	for i, a := range f.args {
		v, err := eval(a, ctx)
		if err != nil {
			return nil, err
		}
		args[i] = v
	}

	nodeArg := func() Node {
		if len(args) == 0 {
			return ctx.node
		}
		if ns, ok := args[0].(NodeSet); ok && len(ns) > 0 {
			return ns[0]
		}
		return nil
	}

	switch f.name {
	case "true":
		return true, nil
	case "false":
		return false, nil
	case "boolean":
		return toBool(args[0]), nil
	case "not":
		return !toBool(args[0]), nil
	case "number":
		if len(args) == 0 {
			return parseNumber(ctx.node.Value()), nil
		}
		return toNumber(args[0]), nil
	case "string":
		if len(args) == 0 {
			return ctx.node.Value(), nil
		}
		return toString(args[0])
	case "count":
		if ns, ok := args[0].(NodeSet); ok {
			return float64(len(ns)), nil
		}
		return float64(0), nil
	case "sum":
		if ns, ok := args[0].(NodeSet); ok {
			sum := 0.0
			for _, n := range ns {
				if v, err := strconv.ParseFloat(n.Value(), 64); err == nil {
					sum += v
				}
			}
			return sum, nil
		}
		return toNumber(args[0]), nil
	case "position":
		return float64(ctx.pos), nil
	case "last":
		return float64(ctx.size), nil
	case "name":
		n := nodeArg()
		if n == nil {
			return "", nil
		}
		return nodeName(n), nil
	case "local-name":
		n := nodeArg()
		if n == nil || n.Type() == RootNode {
			return "", nil
		}
		return n.LocalName(), nil
	case "namespace-uri":
		n := nodeArg()
		if n == nil {
			return "", nil
		}
		return n.NamespaceURI(), nil
	case "concat":
		var b strings.Builder
		for _, a := range args {
			switch v := a.(type) {
			case string:
				b.WriteString(v)
			case NodeSet:
				if len(v) > 0 {
					b.WriteString(v[0].Value())
				}
			}
		}
		return b.String(), nil
	case "contains", "starts-with", "ends-with", "substring-before", "substring-after":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		sub, err := argString(args, 1)
		if err != nil {
			return nil, err
		}
		switch f.name {
		case "contains":
			return strings.Contains(s, sub), nil
		case "starts-with":
			return strings.HasPrefix(s, sub), nil
		case "ends-with":
			return strings.HasSuffix(s, sub), nil
		case "substring-before":
			if i := strings.Index(s, sub); i >= 0 && sub != "" {
				return s[:i], nil
			}
			return "", nil
		case "substring-after":
			if i := strings.Index(s, sub); i >= 0 && sub != "" {
				return s[i+len(sub):], nil
			}
			return "", nil
		}
	case "string-length":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		return float64(len([]rune(s))), nil
	case "normalize-space":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		return strings.Join(strings.Fields(s), " "), nil
	case "lower-case":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		return strings.ToLower(s), nil
	case "translate":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		from, err := argString(args, 1)
		if err != nil {
			return nil, err
		}
		to, err := argString(args, 2)
		if err != nil {
			return nil, err
		}
		fromRunes, toRunes := []rune(from), []rune(to)
		var b strings.Builder
		for _, r := range s {
			idx := -1
			for i, fr := range fromRunes {
				if fr == r {
					idx = i
					break
				}
			}
			if idx == -1 {
				b.WriteRune(r)
			} else if idx < len(toRunes) {
				b.WriteRune(toRunes[idx])
			}
		}
		return b.String(), nil
	case "substring":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		runes := []rune(s)
		start := math.Round(toNumber(args[1]))
		if math.IsNaN(start) {
			return nil, errors.New("runtime error: slice bounds out of range")
		}
		var length float64 = math.Inf(1)
		if len(args) > 2 {
			length = math.Round(toNumber(args[2]))
			if math.IsNaN(length) {
				return "", nil
			}
		}
		if start < 1 {
			if len(args) > 2 {
				length += start - 1
			}
			start = 1
		}
		if start > float64(len(runes)) || length <= 0 {
			return "", nil
		}
		end := float64(len(runes))
		if start-1+length < end {
			end = start - 1 + length
		}
		return string(runes[int(start)-1 : int(end)]), nil
	case "matches":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		pattern, err := argString(args, 1)
		if err != nil {
			return nil, err
		}
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, err
		}
		return re.MatchString(s), nil
	case "replace":
		s, err := argString(args, 0)
		if err != nil {
			return nil, err
		}
		old, err := argString(args, 1)
		if err != nil {
			return nil, err
		}
		repl, err := argString(args, 2)
		if err != nil {
			return nil, err
		}
		return strings.ReplaceAll(s, old, repl), nil
	case "string-join":
		sep, err := argString(args, 1)
		if err != nil {
			return nil, err
		}
		switch v := args[0].(type) {
		case NodeSet:
			parts := make([]string, len(v))
			for i, n := range v {
				parts[i] = n.Value()
			}
			return strings.Join(parts, sep), nil
		default:
			s, err := toString(v)
			if err != nil {
				return nil, err
			}
			return s, nil
		}
	case "reverse":
		if ns, ok := args[0].(NodeSet); ok {
			out := make(NodeSet, len(ns))
			for i, n := range ns {
				out[len(ns)-1-i] = n
			}
			return out, nil
		}
		return nil, errors.New("reverse requires a node-set")
	case "floor":
		return math.Floor(toNumber(args[0])), nil
	case "ceiling":
		return math.Ceil(toNumber(args[0])), nil
	case "round":
		v := math.Round(toNumber(args[0]))
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return int(math.MinInt64), nil
		}
		return int(v), nil
	}
	return nil, fmt.Errorf("unknown function %s", f.name)
}
