package xmldom

import (
	"github.com/xq-reimpl/xq/internal/xpath"
)

// xNode adapts a Node (or one of its attributes) to the xpath.Node interface.
type xNode struct {
	idx   *index
	n     *Node
	attr  int // -1 for regular nodes
	order int
}

type index struct {
	nodes map[*Node]*xNode
	attrs map[*Node][]*xNode
	next  int
}

func (idx *index) register(n *Node) *xNode {
	x := &xNode{idx: idx, n: n, attr: -1, order: idx.next}
	idx.next++
	idx.nodes[n] = x
	if n.Type == ElementNode && len(n.Attr) > 0 {
		attrs := make([]*xNode, len(n.Attr))
		for i := range n.Attr {
			attrs[i] = &xNode{idx: idx, n: n, attr: i, order: idx.next}
			idx.next++
		}
		idx.attrs[n] = attrs
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		idx.register(c)
	}
	return x
}

func (idx *index) get(n *Node) xpath.Node {
	if n == nil {
		return nil
	}
	if x, ok := idx.nodes[n]; ok {
		return x
	}
	// Node outside of the indexed tree (should not normally happen).
	return idx.register(n)
}

// CreateNavigator returns an xpath.Node for the document root.
func CreateNavigator(doc *Node) xpath.Node {
	idx := &index{nodes: map[*Node]*xNode{}, attrs: map[*Node][]*xNode{}}
	return idx.register(doc)
}

// NodeOf returns the DOM node behind an xpath.Node. Attributes are converted
// to a synthetic AttributeNode with a text child holding the value.
func NodeOf(x xpath.Node) *Node {
	xn, ok := x.(*xNode)
	if !ok {
		return nil
	}
	if xn.attr >= 0 {
		attr := xn.n.Attr[xn.attr]
		node := &Node{Type: AttributeNode, Data: attr.Name.Local, Prefix: attr.Name.Space, NamespaceURI: attr.NamespaceURI}
		AddChild(node, &Node{Type: TextNode, Data: attr.Value})
		return node
	}
	return xn.n
}

func (x *xNode) Type() xpath.NodeType {
	if x.attr >= 0 {
		return xpath.AttributeNode
	}
	switch x.n.Type {
	case DocumentNode, DeclarationNode:
		return xpath.RootNode
	case ElementNode, ProcInstNode:
		return xpath.ElementNode
	case TextNode, CharDataNode, NotationNode:
		return xpath.TextNode
	case CommentNode:
		return xpath.CommentNode
	case AttributeNode:
		return xpath.AttributeNode
	}
	return xpath.TextNode
