// Package css implements a CSS selector engine for golang.org/x/net/html trees.
package css

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/net/html"
)

// Matcher reports whether a node matches a selector.
type Matcher interface {
	Match(n *html.Node) bool
}

// Selector is a compiled selector group.
type Selector struct {
	matchers []Matcher
}

// Match reports whether any selector of the group matches the node.
func (s *Selector) Match(n *html.Node) bool {
	for _, m := range s.matchers {
		if m.Match(n) {
			return true
		}
	}
	return false
}

// MatchAll returns all descendants of root matching the selector, in document order.
func (s *Selector) MatchAll(root *html.Node) []*html.Node {
	var out []*html.Node
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode && s.Match(c) {
				out = append(out, c)
			}
			walk(c)
		}
	}
	walk(root)
	return out
}

// Compile parses a selector group.
func Compile(sel string) (*Selector, error) {
	p := &parser{s: sel}
	group, err := p.parseGroup()
	if err != nil {
		return nil, err
	}
	p.skipWhitespace()
	if p.i < len(p.s) {
		return nil, fmt.Errorf("unexpected %q", p.s[p.i:])
	}
	return &Selector{matchers: group}, nil
}

type parser struct {
	s string
	i int
}

func (p *parser) skipWhitespace() bool {
	start := p.i
	for p.i < len(p.s) && (p.s[p.i] == ' ' || p.s[p.i] == '\t' || p.s[p.i] == '\n' || p.s[p.i] == '\r' || p.s[p.i] == '\f') {
		p.i++
	}
	return p.i > start
}

func (p *parser) parseGroup() ([]Matcher, error) {
	var group []Matcher
	for {
		m, err := p.parseSelector()
		if err != nil {
			return nil, err
		}
		group = append(group, m)
		p.skipWhitespace()
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
			continue
		}
		return group, nil
	}
}

type combinedMatcher struct {
	left       Matcher
	combinator byte
	right      Matcher
}

func (c *combinedMatcher) Match(n *html.Node) bool {
	if !c.right.Match(n) {
		return false
	}
	switch c.combinator {
	case ' ':
		for p := n.Parent; p != nil; p = p.Parent {
			if p.Type == html.ElementNode && c.left.Match(p) {
				return true
			}
		}
		return false
	case '>':
		return n.Parent != nil && n.Parent.Type == html.ElementNode && c.left.Match(n.Parent)
	case '+':
		for s := n.PrevSibling; s != nil; s = s.PrevSibling {
			if s.Type == html.ElementNode {
				return c.left.Match(s)
			}
		}
		return false
	case '~':
		for s := n.PrevSibling; s != nil; s = s.PrevSibling {
			if s.Type == html.ElementNode && c.left.Match(s) {
				return true
			}
		}
		return false
	}
	return false
}

func (p *parser) parseSelector() (Matcher, error) {
	p.skipWhitespace()
	left, err := p.parseCompound()
	if err != nil {
		return nil, err
	}
	for {
		hadSpace := p.skipWhitespace()
		if p.i >= len(p.s) || p.s[p.i] == ',' || p.s[p.i] == ')' {
			return left, nil
		}
		var comb byte = ' '
		switch p.s[p.i] {
		case '>', '+', '~':
			comb = p.s[p.i]
			p.i++
			p.skipWhitespace()
		default:
			if !hadSpace {
				return nil, fmt.Errorf("unexpected character %q", p.s[p.i])
			}
		}
		right, err := p.parseCompound()
		if err != nil {
			return nil, err
		}
		left = &combinedMatcher{left: left, combinator: comb, right: right}
	}
}

type andMatcher []Matcher

func (a andMatcher) Match(n *html.Node) bool {
	for _, m := range a {
		if !m.Match(n) {
			return false
		}
	}
	return true
}

type funcMatcher func(*html.Node) bool

func (f funcMatcher) Match(n *html.Node) bool { return f(n) }

func isNameStart(c byte) bool {
	return c == '_' || c == '-' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80 || c == '\\'
}

func isNameChar(c byte) bool {
	return isNameStart(c) || (c >= '0' && c <= '9')
}

func (p *parser) parseIdentifier() (string, error) {
	start := p.i
	if p.i >= len(p.s) || !isNameStart(p.s[p.i]) {
		return "", errors.New("expected identifier")
	}
	for p.i < len(p.s) && isNameChar(p.s[p.i]) {
		if p.s[p.i] == '\\' && p.i+1 < len(p.s) {
			p.i++
		}
		p.i++
	}
	return unescape(p.s[start:p.i]), nil
}

func unescape(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func (p *parser) parseString() (string, error) {
	quote := p.s[p.i]
	p.i++
	start := p.i
	for p.i < len(p.s) && p.s[p.i] != quote {
		if p.s[p.i] == '\\' {
			p.i++
		}
		p.i++
	}
	if p.i >= len(p.s) {
		return "", errors.New("unterminated string")
	}
	val := unescape(p.s[start:p.i])
	p.i++
	return val, nil
}

func (p *parser) parseCompound() (Matcher, error) {
	var matchers andMatcher
	if p.i >= len(p.s) {
		return nil, errors.New("expected selector")
	}
	// type selector
	if p.s[p.i] == '*' {
		p.i++
	} else if isNameStart(p.s[p.i]) {
		name, err := p.parseIdentifier()
		if err != nil {
			return nil, err
		}
		lname := strings.ToLower(name)
		matchers = append(matchers, funcMatcher(func(n *html.Node) bool { return n.Data == lname }))
	}
	for p.i < len(p.s) {
		switch p.s[p.i] {
		case '#':
			p.i++
			start := p.i
			for p.i < len(p.s) && isNameChar(p.s[p.i]) {
				p.i++
			}
			if p.i == start {
				return nil, errors.New("expected id")
			}
			id := unescape(p.s[start:p.i])
			matchers = append(matchers, funcMatcher(func(n *html.Node) bool { return attrValue(n, "id") == id }))
		case '.':
			p.i++
			class, err := p.parseIdentifier()
			if err != nil {
				return nil, err
			}
			matchers = append(matchers, funcMatcher(func(n *html.Node) bool {
				for _, c := range strings.Fields(attrValue(n, "class")) {
					if c == class {
						return true
					}
				}
				return false
			}))
		case '[':
			m, err := p.parseAttribute()
			if err != nil {
				return nil, err
			}
			matchers = append(matchers, m)
		case ':':
			m, err := p.parsePseudo()
			if err != nil {
				return nil, err
			}
			matchers = append(matchers, m)
		default:
			if len(matchers) == 0 && !(p.i > 0 && p.s[p.i-1] == '*') {
				return nil, fmt.Errorf("unexpected character %q", p.s[p.i])
			}
			return matchers, nil
		}
	}
	if len(matchers) == 0 {
		return funcMatcher(func(n *html.Node) bool { return true }), nil
	}
	return matchers, nil
}

func attrValue(n *html.Node, key string) string {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val
		}
	}
	return ""
}

func hasAttr(n *html.Node, key string) bool {
	for _, a := range n.Attr {
		if a.Key == key {
			return true
		}
	}
	return false
}

func (p *parser) parseAttribute() (Matcher, error) {
	p.i++ // [
	p.skipWhitespace()
	key, err := p.parseIdentifier()
	if err != nil {
		return nil, err
	}
	key = strings.ToLower(key)
	p.skipWhitespace()
	if p.i >= len(p.s) {
		return nil, errors.New("unterminated attribute selector")
	}
	if p.s[p.i] == ']' {
		p.i++
		return funcMatcher(func(n *html.Node) bool { return hasAttr(n, key) }), nil
	}
	var op string
	if p.s[p.i] == '=' {
		op = "="
		p.i++
	} else if p.i+1 < len(p.s) && p.s[p.i+1] == '=' && strings.IndexByte("~|^$*!", p.s[p.i]) >= 0 {
		op = p.s[p.i : p.i+2]
		p.i += 2
	} else {
		return nil, errors.New("invalid attribute operator")
	}
	p.skipWhitespace()
	var val string
	if p.i < len(p.s) && (p.s[p.i] == '"' || p.s[p.i] == '\'') {
		val, err = p.parseString()
		if err != nil {
			return nil, err
		}
	} else {
		val, err = p.parseIdentifier()
		if err != nil {
			return nil, err
		}
	}
	p.skipWhitespace()
	if p.i >= len(p.s) || p.s[p.i] != ']' {
		return nil, errors.New("expected ]")
	}
	p.i++

	switch op {
	case "=":
		return funcMatcher(func(n *html.Node) bool { return hasAttr(n, key) && attrValue(n, key) == val }), nil
	case "!=":
		return funcMatcher(func(n *html.Node) bool { return !hasAttr(n, key) || attrValue(n, key) != val }), nil
	case "~=":
		return funcMatcher(func(n *html.Node) bool {
			if !hasAttr(n, key) {
				return false
			}
			for _, f := range strings.Fields(attrValue(n, key)) {
				if f == val {
					return true
				}
			}
			return false
		}), nil
	case "|=":
		return funcMatcher(func(n *html.Node) bool {
			v := attrValue(n, key)
			return hasAttr(n, key) && (v == val || strings.HasPrefix(v, val+"-"))
		}), nil
	case "^=":
		return funcMatcher(func(n *html.Node) bool { return val != "" && hasAttr(n, key) && strings.HasPrefix(attrValue(n, key), val) }), nil
	case "$=":
		return funcMatcher(func(n *html.Node) bool { return val != "" && hasAttr(n, key) && strings.HasSuffix(attrValue(n, key), val) }), nil
	case "*=":
		return funcMatcher(func(n *html.Node) bool { return val != "" && hasAttr(n, key) && strings.Contains(attrValue(n, key), val) }), nil
	}
	return nil, errors.New("invalid attribute operator")
}

func (p *parser) parseParenContent() (string, error) {
	if p.i >= len(p.s) || p.s[p.i] != '(' {
		return "", errors.New("expected (")
	}
	p.i++
	depth := 1
	start := p.i
	for p.i < len(p.s) {
		switch p.s[p.i] {
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				content := p.s[start:p.i]
				p.i++
				return content, nil
			}
		case '"', '\'':
			if _, err := p.parseString(); err != nil {
				return "", err
			}
			continue
		}
		p.i++
	}
	return "", errors.New("unterminated (")
}

func nodeText(n *html.Node) string {
	var b strings.Builder
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.TextNode {
			b.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return b.String()
}

func nodeOwnText(n *html.Node) string {
	var b strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.TextNode {
			b.WriteString(c.Data)
		}
	}
	return b.String()
}

func parseNth(s string) (a, b int, err error) {
	s = strings.ToLower(strings.TrimSpace(s))
	switch s {
	case "odd":
		return 2, 1, nil
	case "even":
		return 2, 0, nil
	}
	if !strings.Contains(s, "n") {
		b, err = strconv.Atoi(s)
		return 0, b, err
	}
	s = strings.ReplaceAll(s, " ", "")
	idx := strings.IndexByte(s, 'n')
	as, bs := s[:idx], s[idx+1:]
	switch as {
	case "", "+":
		a = 1
	case "-":
		a = -1
	default:
		a, err = strconv.Atoi(as)
		if err != nil {
			return
		}
	}
	if bs != "" {
		bs = strings.TrimPrefix(bs, "+")
		b, err = strconv.Atoi(bs)
		if err != nil {
			return
		}
	}
	return a, b, nil
}

func nthMatch(a, b, pos int) bool {
	if a == 0 {
		return pos == b
	}
	n := pos - b
	return n%a == 0 && n/a >= 0
}

func elementIndex(n *html.Node, fromEnd, ofType bool) int {
	count := 1
	if fromEnd {
		for s := n.NextSibling; s != nil; s = s.NextSibling {
			if s.Type == html.ElementNode && (!ofType || s.Data == n.Data) {
				count++
			}
		}
	} else {
		for s := n.PrevSibling; s != nil; s = s.PrevSibling {
			if s.Type == html.ElementNode && (!ofType || s.Data == n.Data) {
				count++
			}
		}
	}
	return count
}

func (p *parser) parsePseudo() (Matcher, error) {
	p.i++ // ':'
	if p.i < len(p.s) && p.s[p.i] == ':' {
		p.i++
	}
	name, err := p.parseIdentifier()
	if err != nil {
		return nil, err
	}
	name = strings.ToLower(name)
	switch name {
	case "not", "has", "haschild":
		content, err := p.parseParenContent()
		if err != nil {
			return nil, err
		}
		sub, err := Compile(content)
		if err != nil {
			return nil, err
		}
		switch name {
		case "not":
			return funcMatcher(func(n *html.Node) bool { return !sub.Match(n) }), nil
		case "has":
			return funcMatcher(func(n *html.Node) bool { return len(sub.MatchAll(n)) > 0 }), nil
		default:
			return funcMatcher(func(n *html.Node) bool {
				for c := n.FirstChild; c != nil; c = c.NextSibling {
					if c.Type == html.ElementNode && sub.Match(c) {
						return true
					}
				}
				return false
			}), nil
		}
	case "contains", "containsown":
		content, err := p.parseParenContent()
		if err != nil {
			return nil, err
		}
		content = strings.TrimSpace(content)
		if len(content) >= 2 && (content[0] == '"' || content[0] == '\'') && content[len(content)-1] == content[0] {
			content = unescape(content[1 : len(content)-1])
		}
		val := strings.ToLower(content)
		if name == "contains" {
