// Package convert transforms an XML document tree into a JSON-compatible value.
package convert

import (
	"strings"

	"github.com/xq-reimpl/xq/internal/xmldom"
)

// XMLToJSON converts the document into a JSON-like structure (maps, slices and
// strings). Elements nested deeper than maxDepth are collapsed to their text
// (maxDepth < 0 means unlimited).
func XMLToJSON(doc *xmldom.Node, maxDepth int) interface{} {
	result := map[string]interface{}{}
	hasElements := false
	for child := doc.FirstChild; child != nil; child = child.NextSibling {
		if child.Type != xmldom.ElementNode {
			continue
		}
		hasElements = true
		result[child.Data] = elementToJSON(child, 0, maxDepth)
	}
	if !hasElements {
		return map[string]interface{}{"text": strings.TrimSpace(doc.InnerText())}
	}
	return result
}

// collapsedText joins the texts of all descendants with line breaks.
func collapsedText(n *xmldom.Node) string {
	var parts []string
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		switch child.Type {
		case xmldom.TextNode, xmldom.CharDataNode:
			if text := strings.TrimSpace(child.Data); text != "" {
				parts = append(parts, text)
			}
		case xmldom.ElementNode:
			parts = append(parts, collapsedText(child))
		}
	}
	return strings.Join(parts, "\n")
}

func elementToJSON(n *xmldom.Node, depth int, maxDepth int) interface{} {
	if maxDepth >= 0 && depth >= maxDepth {
		return collapsedText(n)
	}

	var texts []string
	hasElementChildren := false
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		switch child.Type {
		case xmldom.TextNode, xmldom.CharDataNode:
			if text := strings.TrimSpace(child.Data); text != "" {
				texts = append(texts, text)
			}
		case xmldom.ElementNode:
			hasElementChildren = true
		}
	}

	if len(n.Attr) == 0 && !hasElementChildren {
		if len(texts) == 0 {
			return map[string]interface{}{}
		}
		return strings.Join(texts, "\n")
	}

	result := map[string]interface{}{}
	for _, attr := range n.Attr {
		result["@"+attr.Name.Local] = attr.Value
	}
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if child.Type != xmldom.ElementNode {
			continue
		}
		value := elementToJSON(child, depth+1, maxDepth)
		if existing, ok := result[child.Data]; ok {
			if list, isList := existing.([]interface{}); isList {
				result[child.Data] = append(list, value)
			} else {
				result[child.Data] = []interface{}{existing, value}
			}
		} else {
			result[child.Data] = value
		}
	}
	if len(texts) > 0 {
		result["#text"] = strings.Join(texts, "\n")
	}
	return result
}
