				if stat, err := os.Stdin.Stat(); err == nil && stat.Mode()&os.ModeCharDevice != 0 {
					return cmd.Help()
				}
			}

			if opts.inPlace && len(args) != 1 {
				return errors.New("in-place formatting requires a file path (and only one file path)")
			}

			if opts.attr != "" && opts.query == "" {
				return errors.New("query option (-q) is missed for attribute selection")
			}

			switch {
			case noColorFlag:
				opts.colors = formatter.ColorsDisabled
			case colorFlag:
				opts.colors = formatter.ColorsForced
			default:
				opts.colors = formatter.ColorsDefault
			}
			if opts.inPlace {
				opts.colors = formatter.ColorsDisabled
			}

			var inputs [][]byte
			if len(args) == 0 {
				content, err := io.ReadAll(os.Stdin)
				if err != nil {
					return err
				}
				inputs = append(inputs, content)
			} else {
				for _, path := range args {
					content, err := os.ReadFile(path)
					if err != nil {
						return err
					}
					inputs = append(inputs, content)
				}
			}

			return run(inputs, args, &opts)
		},
	}

	flags := cmd.Flags()
	flags.StringVarP(&opts.attr, "attr", "a", "", "Extract an attribute value instead of node content for provided CSS query")
	flags.BoolVarP(&colorFlag, "color", "c", false, "Force colorful output")
	flags.BoolVar(&opts.compact, "compact", false, "Compact JSON output (no indentation)")
	flags.IntVarP(&opts.depth, "depth", "d", -1, "Maximum nesting depth for JSON output (-1 for unlimited)")
	flags.StringVarP(&opts.extract, "extract", "e", "", "Extract a single node from XML")
	flags.BoolP("help", "h", false, "Print this help message")
	flags.BoolVarP(&opts.html, "html", "m", false, "Use HTML formatter")
	flags.BoolVarP(&opts.inPlace, "in-place", "i", false, "Format file in place")
	flags.IntVar(&indentFlag, "indent", 2, "Use the given number of spaces for indentation")
	flags.BoolVarP(&opts.json, "json", "j", false, "Output the result as JSON")
	flags.BoolVar(&noColorFlag, "no-color", false, "Disable colorful output")
	flags.BoolVarP(&opts.node, "node", "n", false, "Return the node content instead of text")
	flags.StringVarP(&opts.query, "query", "q", "", "Extract the node(s) using CSS selector")
	flags.BoolVar(&tabFlag, "tab", false, "Use tabs for indentation")
	flags.BoolVarP(&versionFlag, "version", "v", false, "Print version information")
	flags.StringVarP(&opts.xpath, "xpath", "x", "", "Extract the node(s) from XML")

	return cmd
}

// Execute runs the root command.
func Execute() {
	if err := NewRootCmd().Execute(); err != nil {
		os.Exit(1)
	}
}

// flushWriter buffers the output but makes sure that everything written so far
// reaches the destination if the program panics.
type flushWriter struct {
	*bufio.Writer
}

func run(inputs [][]byte, paths []string, opts *options) error {
	var dest io.Writer = os.Stdout
	var pager *exec.Cmd
	var pagerStdin io.WriteCloser
	var inPlaceBuf *bytes.Buffer

	if opts.inPlace {
		inPlaceBuf = &bytes.Buffer{}
		dest = inPlaceBuf
	} else if os.Getenv("PAGER") == "less" {
		pager = exec.Command("less", "--quit-if-one-screen", "--no-init", "--RAW-CONTROL-CHARS")
		pager.Stdout = os.Stdout
		pager.Stderr = os.Stderr
		stdin, err := pager.StdinPipe()
		if err == nil {
			if err := pager.Start(); err == nil {
				pagerStdin = stdin
				dest = stdin
			} else {
				pager = nil
			}
		} else {
			pager = nil
		}
	}

	writer := bufio.NewWriterSize(dest, 64*1024)
	defer func() {
		if r := recover(); r != nil {
			writer.Flush()
			panic(r)
		}
	}()

	var lastErr error
	for _, content := range inputs {
		if err := process(content, writer, opts); err != nil {
			lastErr = err
		}
	}
	writer.Flush()

	if pager != nil {
		pagerStdin.Close()
		pager.Wait()
	}

	if opts.inPlace && lastErr == nil {
		if err := os.WriteFile(paths[0], inPlaceBuf.Bytes(), 0644); err != nil {
			return err
		}
	} else if opts.inPlace {
		_ = os.WriteFile(paths[0], inPlaceBuf.Bytes(), 0644)
	}

	if lastErr != nil {
		fmt.Fprintln(os.Stdout, "Error:", lastErr)
		os.Exit(1)
	}
	return nil
}

func detectContentType(content []byte) contentType {
	if len(content) == 0 {
		return contentUnknown
	}
	head10 := content
	if len(head10) > 10 {
		head10 = head10[:10]
	}
	head16 := content
	if len(head16) > 16 {
		head16 = head16[:16]
	}
	if bytes.ContainsAny(head10, "{[") {
		return contentJSON
	}
	if bytes.Contains(bytes.ToLower(head10), []byte("<html")) || bytes.Contains(bytes.ToLower(head16), []byte("<!doctype")) {
		return contentHTML
	}
	return contentXML
}

func process(content []byte, out io.Writer, opts *options) error {
	switch {
	case opts.xpath != "":
		return handleXPath(content, out, opts.xpath, opts.node, false)
	case opts.extract != "":
		return handleXPath(content, out, opts.extract, opts.node, true)
	case opts.query != "":
		return handleQuery(content, out, opts)
	case opts.json:
		return handleJSON(content, out, opts)
	}

	ctype := detectContentType(content)
	if opts.html {
		ctype = contentHTML
	}
	var err error
	switch ctype {
	case contentHTML:
		err = formatter.FormatHtml(bytes.NewReader(content), out, opts.indent, opts.colors)
	case contentXML:
		err = formatter.FormatXml(bytes.NewReader(content), out, opts.indent, opts.colors)
	case contentJSON:
		err = formatter.FormatJson(bytes.NewReader(content), out, opts.indent, opts.colors)
	default:
		return fmt.Errorf("unknown content type: %d", int(ctype))
	}
	if err != nil {
		return err
	}
	io.WriteString(out, "\n")
	return nil
}

func formatNodeXML(node *xmldom.Node, opts *options) (string, error) {
	var buf bytes.Buffer
	err := formatter.FormatXml(strings.NewReader(node.OutputXML(true)), &buf, opts.indent, opts.colors)
	return buf.String(), err
}

func handleXPath(content []byte, out io.Writer, query string, nodeMode bool, single bool) (err error) {
	doc, err := xmldom.Parse(bytes.NewReader(content), xmldom.Options{Strict: false, CharsetReader: formatter.CharsetReader})
	if err != nil {
		return err
	}

	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("XPath error: %v", r)
		}
	}()

	expr, compileErr := xpath.Compile(query)
	if compileErr != nil {
		if single {
			return errors.New("XPath error: expression must evaluate to a node-set")
		}
		return xpath.ErrSyntax
	}

	result, evalErr := expr.Evaluate(xmldom.CreateNavigator(doc))
	if evalErr != nil {
		return fmt.Errorf("XPath error: %v", evalErr)
	}

	opts := &options{indent: "  ", colors: formatter.ColorsDefault}
	_ = opts
	return outputXPathResult(result, out, nodeMode, single, currentOpts)
}

// currentOpts holds the options of the running command (set by run).
var currentOpts *options

func outputXPathResult(result interface{}, out io.Writer, nodeMode bool, single bool, opts *options) error {
	switch v := result.(type) {
	case xpath.NodeSet:
		for _, n := range v {
			node := xmldom.NodeOf(n)
			if nodeMode {
				s, err := formatNodeXML(node, opts)
				if err != nil {
					return err
				}
				fmt.Fprintln(out, s)
			} else {
				fmt.Fprintln(out, strings.TrimSpace(n.Value()))
			}
			if single {
				break
			}
		}
		return nil
	case float64:
		if single {
			return nil
		}
		fmt.Fprintf(out, "%.0f\n", v)
		return nil
	case string:
		if single {
			return nil
		}
		fmt.Fprintln(out, strings.TrimSpace(v))
		return nil
	}
	if single {
		return nil
	}
	return fmt.Errorf("unknown type error: %v", result)
}

func handleQuery(content []byte, out io.Writer, opts *options) error {
	doc, err := html.Parse(bytes.NewReader(content))
	if err != nil {
		return err
	}
	selector, err := css.Compile(opts.query)
	if err != nil {
		return nil
	}
	for _, node := range selector.MatchAll(doc) {
		switch {
		case opts.attr != "":
			value := ""
			for _, a := range node.Attr {
				if a.Key == opts.attr {
					value = a.Val
					break
				}
			}
			fmt.Fprintln(out, value)
		case opts.node:
			var rendered bytes.Buffer
			if err := html.Render(&rendered, node); err != nil {
				return err
			}
			var buf bytes.Buffer
			if err := formatter.FormatHtml(&rendered, &buf, opts.indent, opts.colors); err != nil {
				return err
			}
			fmt.Fprintln(out, buf.String())
		default:
			fmt.Fprintln(out, strings.TrimSpace(nodeText(node)))
		}
	}
	return nil
}

func nodeText(n *html.Node) string {
	var b strings.Builder
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.TextNode {
			b.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(n)
	return b.String()
}

func handleJSON(content []byte, out io.Writer, opts *options) error {
	indent := "  "
	if opts.compact {
		indent = ""
	}

	var value interface{}
	switch detectContentType(content) {
	case contentJSON:
		if err := json.NewDecoder(bytes.NewReader(content)).Decode(&value); err != nil {
			return fmt.Errorf("error while parsing JSON: %w", err)
		}
	case contentUnknown:
		value = map[string]interface{}{"text": ""}
	default:
		doc, err := xmldom.Parse(bytes.NewReader(content), xmldom.Options{Strict: true, CharsetReader: charset.NewReaderLabel})
		if err != nil {
			return fmt.Errorf("error while parsing XML: %w", err)
		}
		value = convert.XMLToJSON(doc, opts.depth)
	}

	encoded, err := json.Marshal(value)
	if err != nil {
		return err
	}
	if err := formatter.FormatJson(bytes.NewReader(encoded), out, indent, opts.colors); err != nil {
		return err
	}
	io.WriteString(out, "\n")
	return nil
}
