}

// parseRawAttrs extracts the attributes of a start tag from its raw bytes.
// Unlike the tokenizer it keeps duplicated attributes (in source order).
func parseRawAttrs(raw []byte) []rawAttr {
	var attrs []rawAttr
	i := 0
	n := len(raw)
	if i < n && raw[i] == '<' {
		i++
	}
	// tag name
	for i < n && !isTagWhitespace(raw[i]) && raw[i] != '/' && raw[i] != '>' {
		i++
	}
	for i < n && isTagWhitespace(raw[i]) {
		i++
	}
	for i < n {
		c := raw[i]
		if c == '>' {
			break
		}
		// attribute key
		keyStart := i
		for i < n {
			c := raw[i]
			if c == '=' && i == keyStart {
				i++
				continue
			}
			if c == '=' || isTagWhitespace(c) || c == '/' || c == '>' {
				break
			}
			i++
		}
		key := raw[keyStart:i]
		// attribute value
		var val []byte
		for i < n && isTagWhitespace(raw[i]) {
			i++
		}
		if i < n && raw[i] == '/' {
			i++
		} else if i < n && raw[i] == '=' {
			i++
			for i < n && isTagWhitespace(raw[i]) {
				i++
			}
			if i < n {
				quote := raw[i]
				switch quote {
				case '>':
				case '\'', '"':
					i++
					start := i
					for i < n && raw[i] != quote {
						i++
					}
					val = raw[start:i]
					if i < n {
						i++
					}
				default:
					start := i
					for i < n && !isTagWhitespace(raw[i]) && raw[i] != '>' {
						i++
					}
					val = raw[start:i]
				}
			}
		}
		if len(key) > 0 {
			k := strings.ToLower(string(bytes.ReplaceAll(key, []byte{0}, []byte("\uFFFD"))))
			v := string(bytes.ReplaceAll(val, []byte{0}, []byte("\uFFFD")))
			v = strings.ReplaceAll(v, "\r\n", "\n")
			v = strings.ReplaceAll(v, "\r", "\n")
			attrs = append(attrs, rawAttr{key: k, val: html.UnescapeString(v)})
		}
		for i < n && isTagWhitespace(raw[i]) {
			i++
		}
	}
	return attrs
}
