random.seed(7)
names = ['a','b','c','d','ns:e']
def gen(depth):
    if depth > 4 or random.random() < 0.3:
        return random.choice(['text', ' sp ', '\n  ind\n', 'x &amp; y', '<![CDATA[cd <x>]]>', '<!-- c -->', ''])
    n = random.choice(names)
    attrs = ''.join(' %s="%s"' % (random.choice(['x','y','n:z']), random.choice(['1','a b','&amp;','"'])) for _ in range(random.randint(0,2)))
    kids = ''.join(gen(depth+1) for _ in range(random.randint(0,4)))
    if not kids and random.random() < 0.5:
        return '<%s%s/>' % (n, attrs)
    return '<%s%s>%s</%s>' % (n, attrs, kids, n)
crashes = 0
for i in range(300):
    doc = '<?xml version="1.0"?><root xmlns:ns="urn:x" xmlns:n="urn:n">' + gen(0) + gen(0) + '</root>'
    for args in ([], ['-m'], ['-j'], ['-x', '//*[1]'], ['-n', '-x', '//*'], ['-q', 'a'], ['-n', '-q', 'root']):
        p = subprocess.run(['./executable'] + args, input=doc.encode(), capture_output=True)
        if p.returncode not in (0, 1) or b'panic' in p.stderr:
            crashes += 1
            print('CRASH', args, doc[:200], p.stderr[:200])
            break
print('crashes:', crashes)
EOF

