// unescapeAttrValue decodes character references the way the HTML tokenizer
// does for attribute values: a named reference without the trailing semicolon
// that is directly followed by "=" is left untouched.
func unescapeAttrValue(s string) string {
	if !strings.Contains(s, "&") {
		return s
	}
	var b strings.Builder
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] != '&' || i+1 >= len(s) || s[i+1] == '#' {
			continue
		}
		j := i + 1
		for j < len(s) && isAlnum(s[j]) {
			j++
		}
		if j > i+1 && j < len(s) && s[j] != ';' && s[j] == '=' {
			// literal: flush the decoded part before it and keep the reference as is
			b.WriteString(html.UnescapeString(s[start:i]))
			b.WriteString(s[i:j])
			start = j
			i = j - 1
		}
	}
	b.WriteString(html.UnescapeString(s[start:]))
	return b.String()
}
'''
