new = '''// recorder keeps track of every byte handed to the decoder so that the raw
// representation of a token can be inspected (used to detect CDATA sections).
type recorder struct {
	r      *bufio.Reader
	buf    *bytes.Buffer
	record bool
}

func (r *recorder) ReadByte() (byte, error) {
	b, err := r.r.ReadByte()
	if err == nil && r.record {
		r.buf.WriteByte(b)
	}
	return b, err
}

func (r *recorder) Read(p []byte) (int, error) {
	// Only used when the decoder hands the reader over to a charset converter;
	// the converted bytes are recorded by a new recorder instead.
	return r.r.Read(p)
}

'''
s = s[:old_start] + new + s[old_end:]
s=s.replace('''	raw := &bytes.Buffer{}
	rec := &recorder{r: bufio.NewReader(r), buf: raw}''','''	raw := &bytes.Buffer{}
	rec := &recorder{r: bufio.NewReader(r), buf: raw, record: true}''')
s=s.replace('''		if converted == nil {
			return nil, nil
		}
		// Keep recording the (converted) bytes to stay aligned with the decoder offsets.
		return &recorder{r: bufio.NewReader(converted), buf: raw}, nil''','''		if converted == nil {
			return nil, nil
		}
